INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Providing excellent customer service is essential for building long-term relationships with clients. When a customer contacts a company with a problem, responding quickly and politely can make a significant difference in how the situation is perceived by that person. Listening carefully to the customer''s concerns before offering a solution shows that their feedback is valued and taken seriously by the whole team. Even when a company cannot fully resolve an issue immediately, keeping the customer informed about the next steps helps maintain trust throughout the process. Training employees to handle difficult situations calmly and professionally is one of the best investments a business can make. Over time, strong customer service often leads to repeat business and positive recommendations from satisfied customers."}'::jsonb, '{"exact": "Providing excellent customer service is essential for building long-term relationships with clients. When a customer contacts a company with a problem, responding quickly and politely can make a significant difference in how the situation is perceived by that person. Listening carefully to the customer''s concerns before offering a solution shows that their feedback is valued and taken seriously by the whole team. Even when a company cannot fully resolve an issue immediately, keeping the customer informed about the next steps helps maintain trust throughout the process. Training employees to handle difficult situations calmly and professionally is one of the best investments a business can make. Over time, strong customer service often leads to repeat business and positive recommendations from satisfied customers."}'::jsonb, 128, 0.50, 'B2', 'approved', 'exam', 'business', 'c2000000-0000-4000-8000-000000000011', 1);
