INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Hana received a difficult complaint call early one morning. Instead of reacting defensively, she listened carefully and apologized sincerely. By the end of the call, the customer thanked her for her patience. Hana felt proud of how she had handled the situation."}'::jsonb, '{"key_points": ["Hana received a difficult complaint call", "she listened and apologized sincerely", "the customer thanked her for her patience", "she felt proud of how she handled it"]}'::jsonb, 43, 0.52, 'B1', 'approved', 'exam', 'business', 'c2000000-0000-4000-8000-000000000014', 1),
('passage_reconstruction', '{"passage": "Tomas noticed a pattern of similar complaints about a product feature. He reported the issue to the product team with examples. Within two weeks, the team released an update fixing the problem. Customer complaints about that feature dropped significantly afterward."}'::jsonb, '{"key_points": ["Tomas noticed a pattern of complaints", "he reported the issue with examples", "the team released a fix within two weeks", "complaints dropped afterward"]}'::jsonb, 40, 0.55, 'B2', 'approved', 'exam', 'business', 'c2000000-0000-4000-8000-000000000014', 2),
('passage_reconstruction', '{"passage": "Thank you for bringing this issue to our attention. We sincerely apologize for the inconvenience caused by the delayed response. Our team is currently reviewing your account, and a representative will contact you within 24 hours with a full resolution."}'::jsonb, '{"key_points": ["apologizes for the delayed response", "the team is reviewing the account", "a representative will contact within 24 hours", "promises a full resolution"]}'::jsonb, 37, 0.56, 'B2', 'approved', 'exam', 'business', 'c2000000-0000-4000-8000-000000000014', 3),
('passage_reconstruction', '{"passage": "I am writing to confirm that your refund has been processed successfully. The amount should appear in your account within three to five business days. Please let us know if you have any further questions or concerns."}'::jsonb, '{"key_points": ["confirms the refund was processed", "funds appear within three to five days", "invites further questions"]}'::jsonb, 35, 0.52, 'B1', 'approved', 'exam', 'business', 'c2000000-0000-4000-8000-000000000014', 4);
INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "You work at a call center. Your supervisor, Ms. Patel, wants to reduce customer wait times without hiring more staff. Write an email to her suggesting three ways to achieve this. Your suggestions must come from the following three themes: self-service options, staff scheduling changes, callback system. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.55, 'B2', 'approved', 'exam', 'business', 'c2000000-0000-4000-8000-000000000015', 1),
('email_writing', '{"prompt": "You work at an online retailer. A customer, Mr. Thompson, complained that he received the wrong item in his order. Write an email to him apologizing and offering a solution. Your response must address the following three themes: an apology for the mix-up, an explanation of the correction process, a goodwill gesture for the inconvenience. You should include all three themes with a clear, professional tone."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'c2000000-0000-4000-8000-000000000015', 2);
